    default int luhnCheckDigit(String customerCode) {
        if (customerCode == null) {
            return 0;
        }
        int sum = 0;
        boolean dbl = true;
        for (int i = customerCode.length() - 1; i >= 0; i--) {
            char c = customerCode.charAt(i);
            if (c < '0' || c > '9') {
